import{_ as a,o as s,c as n,a3 as i}from"./chunks/framework.C6R8kWFE.js";const u=JSON.parse('{"title":"Compiler Architecture & LLVM Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"internals/compiler-architecture.md","filePath":"internals/compiler-architecture.md"}'),l={name:"internals/compiler-architecture.md"};function c(t,e,r,o,p,d){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="compiler-architecture-llvm-pipeline" tabindex="-1">Compiler Architecture &amp; LLVM Pipeline <a class="header-anchor" href="#compiler-architecture-llvm-pipeline" aria-label="Permalink to &quot;Compiler Architecture &amp; LLVM Pipeline&quot;">​</a></h1><p>The <strong>Glue</strong> compiler is a multi-phase, ahead-of-time (AOT) compiler that translates high-level Glue source code into LLVM Intermediate Representation (IR) and produces standalone native binaries using <code>clang</code>.</p><hr><h2 id="compilation-pipeline" tabindex="-1">Compilation Pipeline <a class="header-anchor" href="#compilation-pipeline" aria-label="Permalink to &quot;Compilation Pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │    GlueIR Source Code     │</span></span>
<span class="line"><span>                    │        (*.glueir)         │</span></span>
<span class="line"><span>                    └────────────┬────────────┘</span></span>
<span class="line"><span>                                 │</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │     Lexical Analyzer    │</span></span>
<span class="line"><span>                    │   (lexer.h / lexer.cpp) │</span></span>
<span class="line"><span>                    └────────────┬────────────┘</span></span>
<span class="line"><span>                                 │ Token Stream</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │     Syntax Analyzer     │</span></span>
<span class="line"><span>                    │  (parser.h / parser.cpp)│</span></span>
<span class="line"><span>                    └────────────┬────────────┘</span></span>
<span class="line"><span>                                 │ Abstract Syntax Tree (AST)</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │    Semantic Analyzer    │</span></span>
<span class="line"><span>                    │(semantic.h/semantic.cpp)│</span></span>
<span class="line"><span>                    └────────────┬────────────┘</span></span>
<span class="line"><span>                                 │ Verified AST</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │   LLVM Code Generator   │</span></span>
<span class="line"><span>                    │ (codegen.h / codegen.cpp│</span></span>
<span class="line"><span>                    └────────────┬────────────┘</span></span>
<span class="line"><span>                                 │ LLVM IR (.ll)</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>                    ┌─────────────────────────┐</span></span>
<span class="line"><span>                    │      Clang Backend      │</span></span>
<span class="line"><span>                    │ (Native Executable Binary│</span></span>
<span class="line"><span>                    └─────────────────────────┘</span></span></code></pre></div><hr><h2 id="compiler-subsystems" tabindex="-1">Compiler Subsystems <a class="header-anchor" href="#compiler-subsystems" aria-label="Permalink to &quot;Compiler Subsystems&quot;">​</a></h2><h3 id="_1-lexer-src-lexer" tabindex="-1">1. Lexer (<code>../../src/lexer</code>) <a class="header-anchor" href="#_1-lexer-src-lexer" aria-label="Permalink to &quot;1. Lexer (\`../../src/lexer\`)&quot;">​</a></h3><ul><li>Scans raw character streams from input files.</li><li>Generates structured <code>Token</code> instances (<code>TokenType</code>, <code>value</code>, <code>line</code>, <code>column</code>).</li><li>Strips whitespace and single-line <code>//</code> comments.</li><li>Custom tokenization of Glue block comments <code>/*g ... g*/</code>.</li><li>Recognizes integer numbers, float literals (<code>12.5f</code>), double literals (<code>12.5</code>), strings, operators, and language keywords (<code>func</code>, <code>shout</code>, <code>const</code>, <code>sticky</code>, etc.).</li></ul><h3 id="_2-abstract-syntax-tree-src-ast" tabindex="-1">2. Abstract Syntax Tree (<code>../../src/AST</code>) <a class="header-anchor" href="#_2-abstract-syntax-tree-src-ast" aria-label="Permalink to &quot;2. Abstract Syntax Tree (\`../../src/AST\`)&quot;">​</a></h3><ul><li>Represents program constructs in a hierarchical <code>ASTNode</code> graph.</li><li>Node types include <code>PROGRAM</code>, <code>FUNCTION_DECLARATION</code>, <code>FUNCTION_CALL</code>, <code>DECLARATION</code>, <code>ASSIGNMENT</code>, <code>IF_STATEMENT</code>, <code>WHILE_STATEMENT</code>, <code>BINARY_OPERATION</code>, and primitive literal nodes.</li><li>Preserves token line numbers and mutability flags (<code>isConst</code>, <code>isSticky</code>).</li></ul><h3 id="_3-parser-src-parser" tabindex="-1">3. Parser (<code>../../src/parser</code>) <a class="header-anchor" href="#_3-parser-src-parser" aria-label="Permalink to &quot;3. Parser (\`../../src/parser\`)&quot;">​</a></h3><ul><li>Implements a recursive descent parser.</li><li>Enforces grammar rules: top-level declarations, statement blocks, expressions with operator precedence hierarchy (Logical OR -&gt; Logical AND -&gt; Relational -&gt; Additive -&gt; Multiplicative -&gt; Literals).</li><li>Produces meaningful <code>ParseError</code> diagnostics with line and column pointers upon syntax errors.</li></ul><h3 id="_4-semantic-analyzer-src-semantic" tabindex="-1">4. Semantic Analyzer (<code>../../src/semantic</code>) <a class="header-anchor" href="#_4-semantic-analyzer-src-semantic" aria-label="Permalink to &quot;4. Semantic Analyzer (\`../../src/semantic\`)&quot;">​</a></h3><ul><li>Maintains a symbol table tracking identifiers, data types, and mutability states.</li><li>Verifies that <code>main</code> exists, returns <code>int</code>, and terminates with a return statement.</li><li>Enforces strict mutability rules: <ul><li>Reassignment to <code>const</code> symbols is rejected at compile-time.</li><li>Reassignment to <code>sticky</code> symbols is permitted <strong>exactly once</strong> (<code>stickyUsed = true</code>), rejecting any second assignment.</li></ul></li><li>Verifies type compatibility across declarations and assignments.</li></ul><h3 id="_5-llvm-code-generator-src-codegen" tabindex="-1">5. LLVM Code Generator (<code>../../src/codegen</code>) <a class="header-anchor" href="#_5-llvm-code-generator-src-codegen" aria-label="Permalink to &quot;5. LLVM Code Generator (\`../../src/codegen\`)&quot;">​</a></h3><ul><li>Utilizes <code>llvm::LLVMContext</code>, <code>llvm::Module</code>, and <code>llvm::IRBuilder&lt;&gt;</code>.</li><li>Creates native function entry points and handles stack memory via <code>AllocaInst</code>.</li><li>Dynamically generates <code>printf</code> format strings and variable calls for <code>shout</code>.</li><li>Generates conditional branches and phi nodes for <code>if</code>/<code>else</code> and <code>while</code> constructs.</li><li>Emits formatted LLVM assembly (<code>glue.ll</code>) and invokes <code>clang</code> to produce the final executable.</li></ul>`,17)])])}const h=a(l,[["render",c]]);export{u as __pageData,h as default};
